let walkCursor=-1;
const walk=['brief','brand','learnings','researcher','source_review','strategist','writer','editor','verifier','researcher','source_review','writer','verifier','visual','scheduler','published','metrics','learner','learnings','audit'];
function playbackLabels(){document.querySelectorAll('[data-play="play"]').forEach(b=>{b.textContent=timer?'Ⅱ Pause':b.id==='play'?'▷ Play':'▷ Play trace';b.setAttribute('aria-pressed',String(!!timer))})}
function stop(){if(timer)clearInterval(timer);timer=null;playbackLabels()}
function walkthrough(action){
 if(action!=='play')stop();
 if(action==='play'&&timer){stop();return}
 if(action==='prev')walkCursor=Math.max(0,walkCursor-1);
 else if(action==='next')walkCursor=Math.min(walk.length-1,walkCursor+1);
 else if(action==='reset'||action==='latest')walkCursor=0;
 else if(action==='play'){
  if(walkCursor<0||walkCursor>=walk.length-1)walkCursor=0;
  timer=setInterval(()=>{walkCursor=Math.min(walk.length-1,walkCursor+1);if(walkCursor===walk.length-1)stop();renderGraph()},1800/speed);
 }
 playbackLabels();renderGraph();
}
